{
  "name": "meilisearch/search-bundle",
  "description": "Seamless integration of Meilisearch into your Symfony project.",
  "keywords": [
    "meilisearch",
    "instant",
    "search",
    "api",
    "symfony",
    "bundle"
  ],
  "type": "symfony-bundle",
  "license": "MIT",
  "authors": [
    {
      "name": "David Sanchez",
      "email": "david38sanchez@gmail.com"
    }
  ],
  "require": {
    "php": "^8.1",
    "ext-json": "*",
    "meilisearch/meilisearch-php": "^1.16 || v2.0.0-beta.5",
    "symfony/config": "^6.4 || ^7.0 || ^8.0",
    "symfony/dependency-injection": "^6.4 || ^7.0 || ^8.0",
    "symfony/event-dispatcher": "^6.4 || ^7.0 || ^8.0",
    "symfony/http-kernel": "^6.4 || ^7.0 || ^8.0",
    "symfony/property-access": "^6.4 || ^7.0 || ^8.0",
    "symfony/serializer": "^6.4 || ^7.0 || ^8.0"
  },
  "require-dev": {
    "doctrine/doctrine-bundle": "^2.10 || ^3.0",
    "doctrine/orm": "^2.12 || ^3.0",
    "matthiasnoback/symfony-config-test": "^6.1",
    "matthiasnoback/symfony-dependency-injection-test": "^6.2",
    "nikic/php-parser": "^5.6.2",
    "nyholm/psr7": "^1.8.2",
    "php-cs-fixer/shim": "^3.90.0",
    "phpstan/extension-installer": "^1.4.3",
    "phpstan/phpstan": "^2.1.32",
    "phpstan/phpstan-doctrine": "^2.0.11",
    "phpstan/phpstan-phpunit": "^2.0.8",
    "phpstan/phpstan-symfony": "^2.0.8",
    "phpunit/php-code-coverage": "^10.1.16",
    "phpunit/phpunit": "^10.5.60",
    "symfony/doctrine-bridge": "^6.4 || ^7.0 || ^8.0",
    "symfony/filesystem": "^6.4 || ^7.0 || ^8.0",
    "symfony/framework-bundle": "^6.4 || ^7.0 || ^8.0",
    "symfony/http-client": "^6.4.15 || ^7.1.8 || ^8.0",
    "symfony/yaml": "^6.4 || ^7.0 || ^8.0",
    "symfony/var-exporter": "^6.4 || ^7.0 || ^8.0"
  },
  "conflict": {
    "symfony/doctrine-bridge": ">=6.4.42 <6.4.44 || >=7.4.14 <7.4.16 || >=8.0.14 <8.1.3"
  },
  "autoload": {
    "psr-4": {
      "Meilisearch\\Bundle\\": "src/"
    },
    "files": [
      "src/polyfill.php"
    ]
  },
  "autoload-dev": {
    "psr-4": {
      "Meilisearch\\Bundle\\Tests\\": "tests/"
    }
  },
  "config": {
    "sort-packages": true,
    "allow-plugins": {
      "phpstan/extension-installer": true,
      "php-http/discovery": true
    }
  },
  "scripts": {
    "phpstan": "./vendor/bin/phpstan",
    "test:unit": "./vendor/bin/phpunit --use-baseline phpunit.baseline.xml --colors=always",
    "test:unit:coverage": "XDEBUG_MODE=coverage ./vendor/bin/phpunit --use-baseline phpunit.baseline.xml --colors=always --coverage-html=tests/coverage",
    "lint:check": "./vendor/bin/php-cs-fixer fix -v --using-cache=no --dry-run",
    "lint:fix": "./vendor/bin/php-cs-fixer fix -v --using-cache=no"
  }
}

